/**
 * Get Webhook Delivery
 * Retrieves one delivery with its per-attempt log, including response status codes and body snippets. Requires Platform Bearer token.
 */
export const getWebhookDelivery = <ThrowOnError extends boolean = false>(options: Options<GetWebhookDeliveryData, ThrowOnError>) => {
    return (options.client ?? client).get<GetWebhookDeliveryResponses, GetWebhookDeliveryErrors, ThrowOnError>({
        security: [
            {
                scheme: 'bearer',
                type: 'http'
            }
        ],
        url: '/v1/products/{product_id}/webhook-endpoints/{webhook_endpoint_id}/deliveries/{delivery_id}',
        ...options
    });
};

/**
 * Retry Webhook Delivery
 * Replays a finished delivery as a new delivery pointing back at the original. The frozen request body is reused byte-for-byte, so the replay carries the same event with a fresh signature. Replays of replays are rejected. Requires Platform Bearer token.
 */
export const retryWebhookDelivery = <ThrowOnError extends boolean = false>(options: Options<RetryWebhookDeliveryData, ThrowOnError>) => {
    return (options.client ?? client).post<RetryWebhookDeliveryResponses, RetryWebhookDeliveryErrors, ThrowOnError>({
        security: [
            {
                scheme: 'bearer',
                type: 'http'
            }
        ],
        url: '/v1/products/{product_id}/webhook-endpoints/{webhook_endpoint_id}/deliveries/{delivery_id}/retry',
        ...options
    });
};

/**
 * List Webhook Event Types
 * Returns the catalog of emittable event types with their groups and descriptions. Endpoint subscriptions are validated against it, and the admin UI's picker is built from it.
 */
export const listWebhookEventTypes = <ThrowOnError extends boolean = false>(options?: Options<ListWebhookEventTypesData, ThrowOnError>) => {
    return (options?.client ?? client).get<ListWebhookEventTypesResponses, ListWebhookEventTypesErrors, ThrowOnError>({
        security: [
            {
                scheme: 'bearer',
                type: 'http'
            }
        ],
        url: '/v1/webhook-event-types',
        ...options
    });
};
